-- Day 1 DT-01 / DT-60: capture state companions for the optional event envelope fields.
-- The event log is append only and holds no rows that need rewriting: the companion defaults to not_captured, and the shared fill trigger
-- sets it to captured on insert when the field carries a value. The integrity hash covers named envelope fields only, so the chain is unchanged.
alter table public.t3a_event_log
  add column if not exists subject_id_capture_state text not null default 'not_captured' check (subject_id_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists session_id_capture_state text not null default 'not_captured' check (session_id_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists correlation_id_capture_state text not null default 'not_captured' check (correlation_id_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists source_system_capture_state text not null default 'not_captured' check (source_system_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists event_sequence_no_capture_state text not null default 'not_captured' check (event_sequence_no_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists policy_decision_ref_capture_state text not null default 'not_captured' check (policy_decision_ref_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists change_request_ref_capture_state text not null default 'not_captured' check (change_request_ref_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served')),
  add column if not exists application_session_id_capture_state text not null default 'not_captured' check (application_session_id_capture_state in ('captured', 'not_captured', 'never_asked', 'declined', 'no_response', 'not_applicable', 'technical_failure', 'withdrawn', 'not_authored', 'not_served'));

drop trigger if exists t3a_capture_state_fill on public.t3a_event_log;
create trigger t3a_capture_state_fill before insert on public.t3a_event_log for each row execute function public.t3a_capture_state_fill('subject_id:subject_id_capture_state', 'session_id:session_id_capture_state', 'correlation_id:correlation_id_capture_state', 'source_system:source_system_capture_state', 'event_sequence_no:event_sequence_no_capture_state', 'policy_decision_ref:policy_decision_ref_capture_state', 'change_request_ref:change_request_ref_capture_state', 'application_session_id:application_session_id_capture_state');

update public.t3a_field_physical_map m set capture_state_column = x.cs
  from (values ('N.subject_id', 'subject_id_capture_state'), ('N.session_id', 'session_id_capture_state'), ('N.correlation_id', 'correlation_id_capture_state'), ('N.source_system', 'source_system_capture_state'), ('N.event_sequence_no', 'event_sequence_no_capture_state'), ('N.policy_decision_ref', 'policy_decision_ref_capture_state'), ('N.change_request_ref', 'change_request_ref_capture_state'), ('N.application_session_id', 'application_session_id_capture_state')) as x(qn, cs)
 where m.qualified_name = x.qn and m.dictionary_version = '1.3' and m.capture_state_column is distinct from x.cs;
